async function api<T>(path:string,init:RequestInit={}):Promise<T>{const r=await fetch(`${import.meta.env.VITE_API_BASE||'/api'}${path}`,init);if(!r.ok){let m=`请求失败（HTTP ${r.status}）`;try{const j=await r.json();if(typeof j.detail==='string')m=j.detail;}catch{}throw Error(m);}if(r.status===204)return undefined as T;return (r.headers.get('content-type')||'').includes('json')?r.json():r.blob() as T;}
