 useEffect(()=>{let live=true;Promise.all([api<Meta>('/meta'),api<Task[]>('/tasks'),api<Provider[]>('/providers'),api<Env[]>('/environments'),api<Settings>('/settings')]).then(([m,t,p,e,s])=>{if(live){setMeta(m);setTasks(t);if(t[0])acceptTask(t[0]);else setTask(null);setProviders(p);setEnvs(e);setSettings(s)}}).catch(e=>live&&setError(`连接本地后台失败：${errText(e)}`));return()=>{live=false}},[]);
