 const patch=async(body:Record<string,unknown>)=>{if(!task)return;if(manualModelNumbers.pending)throw Error('手动模型数字尚待处理，请先修正输入、明确采用或回到当前配置数值，再保存。');if(caseDirty)throw Error("请先保存或撤销验收样例草稿。");const t=await api<Task>(`/tasks/${task.id}`,post('PATCH',{...body,requirements:task.requirements,configuration:task.configuration,environment_id:task.environment_id}));manualModelNumbers.acknowledge(t);acceptTask(t);setTasks(xs=>xs.map(x=>x.id===t.id?t:x));setNotice('已保存到本地后台。')};
 const create=()=>withBusy('创建中',async()=>{if(hasUnsaved)throw Error('当前有未保存编辑，请先保存或处理后再创建任务。');if(!newType)throw Error('请主动选择应用类型。');const t=await api<Task>('/tasks',post('POST',{name:newName.trim()||'未命名任务',app_type:newType}));setTasks(xs=>[t,...xs]);acceptTask(t);setPage('需求');setModal('');setNotice('任务已由本地后台创建。')});
 useEffect(()=>{setStreamInterview(false)},[task?.id]);
 const interview=(content:string,mode:'review'|'discussion'=chatMode)=>{if(!task||!content.trim())return;const submittedDraft=msg;void withBusy('正在请求真实模型接口',async()=>{if(hasUnsaved)throw Error('请先保存或处理当前草稿，再发送对话。');const t=await api<Task>(`/tasks/${task.id}/messages`,post('POST',{content,stream_response:streamInterview,mode}));acceptTask(t);setTasks(xs=>xs.map(x=>x.id===t.id?t:x));setMsg(current=>current===submittedDraft&&current.trim()===content.trim()?'':current)})};
 const confirm=(kind:'requirements'|'configuration')=>task&&withBusy('正在保存并确认当前修订',async()=>{if(kind==='configuration'&&task.plan_review_required===true&&['workflow','advanced-chat'].includes(task.app_type)&&!task.workflow_plan&&!task.dsl_reference)throw Error('请先在流程页生成并保存完整流程，再确认配置；不会用基础模板替代业务分支。');if(manualModelNumbers.pending)throw Error('手动模型数字尚待处理，请先修正输入、明确采用或回到当前配置数值，再确认。');if(caseDirty)throw Error('请先保存或撤销验收样例草稿，再确认需求与配置。');if(kind==='configuration'&&planIsStale)throw Error('流程计划已过期，请先重新生成或编辑保存并复核。');if(kind==='configuration'&&(requirementsUnsaved||planDirty))throw Error('需求或流程计划有未保存修改，请先保存并确认需求/流程，再确认配置。');const body=kind==='requirements'?{requirements:task.requirements,configuration:task.configuration,environment_id:task.environment_id}:{environment_id:task.environment_id,configuration:task.configuration};const saved=await api<Task>(`/tasks/${task.id}`,post('PATCH',body));manualModelNumbers.acknowledge(saved);acceptTask(saved);setTasks(xs=>xs.map(x=>x.id===saved.id?saved:x));const t=await api<Task>(`/tasks/${task.id}/confirm`,post('POST',{kind,revision:saved.revision}));manualModelNumbers.acknowledge(t);acceptTask(t);setTasks(xs=>xs.map(x=>x.id===t.id?t:x));setNotice('当前编辑内容已保存，并按新修订完成确认。')});
