 const build=()=>task&&withBusy('后台静态检查及构建中',async()=>{if(task.plan_review_required===true&&['workflow','advanced-chat'].includes(task.app_type)&&!task.workflow_plan&&!task.dsl_reference)throw Error('请先生成、核对并保存完整流程；没有显式计划时不会使用基础模板。');if(hasUnsaved)throw Error('有未保存修改，请先保存并确认。');if(planIsStale)throw Error('流程计划已过期，请先重新生成或编辑保存并复核。');if(!task.requirements_confirmed||!task.configuration_confirmed)throw Error('请先确认当前修订的需求和配置。');const t=await api<Task>(`/tasks/${task.id}/build`,post('POST',{revision:task.revision}));acceptTask(t);setTasks(xs=>xs.map(x=>x.id===t.id?t:x));const d=await api<{content:string;validation:typeof valid}>(`/tasks/${task.id}/dsl`);setDsl(d.content);setValid(d.validation);setDslKey(`${t.id}:${t.revision}:${taskSignature(t)}:null`);setNotice('后台已完成构建。静态检查不代表真实导入或运行。')});
