   const t=await api<Task>(`/tasks/${task.id}/run`,post('POST',payload));acceptTask(t);setTasks(xs=>xs.map(x=>x.id===t.id?t:x));setNotice(selectedCaseId?'当前样例已返回实际运行和规则检查记录。':'自由试跑已返回；未绑定验收样例，不计入样例通过数。');
