 const selectedCase=(task?.test_cases||[]).find(c=>c.id===selectedCaseId);const title=task?.name||'创建你的第一个任务';const buildKey=task?`${task.id}:${task.revision}:${taskSignature(task)}:${JSON.stringify(planDirty?planText:null)}`:'';const runEnvironment=task?envs.find(e=>e.id===task.environment_id):undefined;const planIsStale=!!task&&(task.plan_stale===true||planInfo?.stale===true);const canRun=!!task&&['workflow','advanced-chat','agent'].includes(task.app_type)&&['imported','run_completed','completed','error','paused'].includes(task.status)&&task.requirements_confirmed&&task.configuration_confirmed&&!hasUnsaved&&!planIsStale&&!!task.dify_app_id&&!!runEnvironment?.has_service_api_key&&runEnvironment.service_app_id===task.dify_app_id;let planPreview:WorkflowPlan|null=null,planUnsafeNumbers=false;if(planText.trim()){try{const parsed=JSON.parse(planText);planUnsafeNumbers=unsafePlanNumbers(parsed);planPreview=planUnsafeNumbers?null:asPlan(parsed)}catch{planPreview=null}}const missingExactSource=!!task&&!planDirty&&planUnsafeNumbers&&!(exactPlanCache.current?.id===task.id&&exactPlanCache.current.revision===task.revision&&exactPlanCache.current.text===planText);
 const saveProvider=async(data:Record<string,unknown>)=>{if(busy)throw Error('请等待当前操作完成。');setBusy('保存模型服务');setError('');try{const id=form.id;const p=id?await api<Provider>(`/providers/${id}`,post('PATCH',data)):await api<Provider>('/providers',post('POST',data));setProviders(xs=>id?xs.map(x=>x.id===id?p:x):[...xs,p]);clearProbe(p.id);setForm({});setModal('models');setNotice('模型配置已保存。可以测试连接；测试会产生少量模型调用。')}finally{setBusy('')}};
 const saveEnv=()=>withBusy('保存 Dify 环境',async()=>{const id=form.id;const data={name:form.name,base_url:form.base_url,version:form.version,service_app_id:form.service_app_id||'',...(form.console_token?{console_token:form.console_token}:{}),...(form.csrf_token?{csrf_token:form.csrf_token}:{}),...(form.service_api_key?{service_api_key:form.service_api_key}:{}),...(form.dataset_api_key?{dataset_api_key:form.dataset_api_key}:{})};const e=id?await api<Env>(`/environments/${id}`,post('PATCH',data)):await api<Env>('/environments',post('POST',data));setEnvs(xs=>id?xs.map(x=>x.id===id?e:x):[...xs,e]);if(task?.environment_id===e.id)await refreshOne(task.id);setModal('');setNotice('环境设置已保存，关联任务已刷新；后台返回的 revision 与确认状态已同步。')})
