 const savePlan=()=>task&&withBusy('后台正在校验并保存流程计划',async()=>{if(taskDraftUnsaved||caseDirty)throw Error('需求、配置或验收样例有未保存修改，请先保存并确认，再保存流程计划。');let plan:unknown;try{plan=JSON.parse(planText)}catch{throw Error('流程计划不是有效 JSON，请先修正格式。')}if(!plan||typeof plan!=='object'||Array.isArray(plan))throw Error('流程计划顶层必须是 JSON 对象。');const t=await api<Task>(`/tasks/${task.id}/plan`,post('POST',{plan_text:planText,revision:task.revision}));planDirtyRef.current=false;setPlanDirty(false);acceptTask(t);setTasks(xs=>xs.map(x=>x.id===t.id?t:x));setPlanInfo(null);setNotice('流程计划已由后台校验并保存；请重新确认配置后再构建。')});
